package com.nook.phone;

import android.content.Context;
import android.net.Uri;
import android.security.keystore.KeyGenParameterSpec;
import android.security.keystore.KeyProperties;
import android.util.Base64;
import org.json.JSONObject;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.cert.X509Certificate;
import javax.crypto.*;
import javax.crypto.spec.GCMParameterSpec;
import javax.net.ssl.*;

/** A paired certificate must match before any pairing code or bearer token is sent. */
public final class NookApi {
    private static final class PcError extends Exception {PcError(String message){super(message);}}
    private final Context context;
    private String address="",pin="",token="";private JSONObject relay=null;private long lastDiscovery=0;
    public NookApi(Context context){this.context=context.getApplicationContext();try{String stored=context.getSharedPreferences("nook",0).getString("pair","");if(!stored.isEmpty()){String[] parts=stored.split("\\.",2);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(parts[0],Base64.NO_WRAP)));JSONObject data=new JSONObject(new String(cipher.doFinal(Base64.decode(parts[1],Base64.NO_WRAP)),StandardCharsets.UTF_8));address=data.getString("url");pin=data.getString("pin");token=data.getString("token");relay=data.optJSONObject("relay");validate(address,pin);}}catch(Exception ignored){address="";pin="";token="";}}
    private SecretKey key() throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias("NookPair")){KeyGenerator generator=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder("NookPair",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());generator.generateKey();}return (SecretKey)store.getKey("NookPair",null);}
    public static void validate(String address,String pin) throws Exception{URI uri=new URI(address);String host=uri.getHost();if(!"https".equals(uri.getScheme())||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null||!"".equals(uri.getPath())&& !"/".equals(uri.getPath())||uri.getPort()<1024||uri.getPort()>65535||host==null||!host.matches("[0-9.]+")||!pin.matches("[a-fA-F0-9]{64}"))throw new Exception("Use the HTTPS pairing link displayed on your PC.");String[] pieces=host.split("\\.");if(pieces.length!=4)throw new Exception("Invalid local address.");int[] p=new int[4];for(int i=0;i<4;i++){p[i]=Integer.parseInt(pieces[i]);if(p[i]<0||p[i]>255)throw new Exception("Invalid local address.");}if(!(p[0]==10||p[0]==192&&p[1]==168||p[0]==172&&p[1]>=16&&p[1]<=31||p[0]==169&&p[1]==254))throw new Exception("Pair with a PC on your local network.");}
    public boolean paired(){return !token.isEmpty();}
    public void pair(String link) throws Exception{Uri uri=Uri.parse(link);if(!"nook".equals(uri.getScheme())||!"pair".equals(uri.getHost()))throw new Exception("Paste a Nook pairing link.");String next=uri.getQueryParameter("url"),fingerprint=uri.getQueryParameter("pin"),code=uri.getQueryParameter("code");if(next==null||fingerprint==null||code==null||!code.matches("[0-9]{6}"))throw new Exception("The pairing link is incomplete.");validate(next,fingerprint);String oldAddress=address,oldPin=pin,oldToken=token;address=next.replaceAll("/$","");pin=fingerprint.toLowerCase();token="";try{JSONObject result=request("/pair","POST",new JSONObject().put("code",code));token=result.getString("token");relay=null;save();try{refreshRelay();}catch(Exception ignored){}}catch(Exception e){address=oldAddress;pin=oldPin;token=oldToken;throw e;}}
    private void save() throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());String raw=new JSONObject().put("url",address).put("pin",pin).put("token",token).put("relay",relay==null?JSONObject.NULL:relay).toString();String encrypted=Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+"."+Base64.encodeToString(cipher.doFinal(raw.getBytes(StandardCharsets.UTF_8)),Base64.NO_WRAP);context.getSharedPreferences("nook",0).edit().putString("pair",encrypted).apply();}
    public void clear(){relay=null;ReconnectJob.enable(context,false);token="";address="";pin="";context.getSharedPreferences("nook",0).edit().remove("pair").remove("status").remove("active").remove("waiting").apply();NookWidget.update(context,"Disconnected");}
    public void refreshRelay() throws Exception{relay=direct("/relay-config","GET",null).optJSONObject("relay");save();}
    public String diagnostics(){return context.getSharedPreferences("nook",0).getString("transport","No successful connection yet")+"\n"+(relay==null?"Remote relay not configured. Reconnect locally after enabling it on PC.":"Encrypted relay available.")+"\nIf pairing expired or the PC certificate changed, generate a new pairing link. Windows Firewall and guest Wi-Fi can block discovery.";}
    public JSONObject request(String path,String method,JSONObject payload)throws Exception{
      try{if(!method.equals("GET"))direct("/.well-known/nook","GET",null);else{JSONObject r=direct(path,method,payload);mark("Local Wi-Fi · "+new java.util.Date());return r;}}
      catch(Exception e){if(e instanceof javax.net.ssl.SSLException||e instanceof PcError)throw e;boolean discovered=false;if(paired()&&System.currentTimeMillis()-lastDiscovery>15000){lastDiscovery=System.currentTimeMillis();String old=address;for(String candidate:Discovery.find(context,pin)){try{address=candidate;direct("/.well-known/nook","GET",null);save();discovered=true;break;}catch(Exception ignored){address=old;}}}if(!discovered){if(relay!=null&&paired()){JSONObject r=RelayTransport.request(relay,token,path,method,payload);mark("Encrypted relay · "+new java.util.Date());return r;}throw new Exception("Cannot reach your PC. Use the same Wi-Fi, enable phone access, and check Windows Firewall. "+e.getMessage());}}
      JSONObject result=direct(path,method,payload);mark("Local Wi-Fi · "+new java.util.Date());return result;
    }
    private void mark(String message){context.getSharedPreferences("nook",0).edit().putString("transport",message).apply();}
    private JSONObject direct(String path,String method,JSONObject payload) throws Exception{validate(address,pin);if(!path.startsWith("/")||path.contains("://"))throw new Exception("Invalid request.");final String expected=pin;TrustManager[] managers={new X509TrustManager(){public X509Certificate[] getAcceptedIssuers(){return new X509Certificate[0];}public void checkClientTrusted(X509Certificate[] chain,String auth) throws java.security.cert.CertificateException{throw new java.security.cert.CertificateException();}public void checkServerTrusted(X509Certificate[] chain,String auth) throws java.security.cert.CertificateException{try{if(chain.length<1)throw new Exception();chain[0].checkValidity();byte[] digest=MessageDigest.getInstance("SHA-256").digest(chain[0].getEncoded());StringBuilder hex=new StringBuilder();for(byte b:digest)hex.append(String.format("%02x",b&255));if(!MessageDigest.isEqual(hex.toString().getBytes(StandardCharsets.US_ASCII),expected.getBytes(StandardCharsets.US_ASCII)))throw new Exception();}catch(Exception e){throw new java.security.cert.CertificateException("PC certificate changed. Re-pair from your PC.");}}}};SSLContext ssl=SSLContext.getInstance("TLS");ssl.init(null,managers,new SecureRandom());HttpsURLConnection connection=(HttpsURLConnection)new URL(address+path).openConnection();connection.setSSLSocketFactory(ssl.getSocketFactory());connection.setHostnameVerifier((host,session)->host.equals(URI.create(address).getHost()));connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(10000);connection.setReadTimeout(path.equals("/chat")?125000:15000);connection.setRequestMethod(method);connection.setRequestProperty("Content-Type","application/json");if(!token.isEmpty())connection.setRequestProperty("Authorization","Bearer "+token);try{if(payload!=null){connection.setDoOutput(true);try(OutputStream out=connection.getOutputStream()){out.write(payload.toString().getBytes(StandardCharsets.UTF_8));}}int status=connection.getResponseCode();InputStream stream=status>=400?connection.getErrorStream():connection.getInputStream();if(stream==null)throw new Exception("The PC did not return a response.");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=stream){byte[] buffer=new byte[4096];int count;while((count=in.read(buffer))!=-1){if(bytes.size()+count>2_000_000)throw new Exception("Response too large.");bytes.write(buffer,0,count);}}JSONObject result=new JSONObject(bytes.toString(StandardCharsets.UTF_8.name()));if(status==401&&!path.equals("/pair"))clear();if(status>=300)throw new PcError(result.optString("error","PC request failed."));return result;}finally{connection.disconnect();}}
}
